import { field, select, checkbox, textarea, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "wtHost", label: "Server host", value: "example.com" })}${field({ id: "wtPort", label: "Port", type: "number", value: "4433", help: "WebTransport typically uses UDP port 4433" })}</div><div class="field-grid">${field({ id: "wtPath", label: "Path", value: "/webtransport" })}${checkbox({ id: "wtHash", label: "Include serverCertificateHashes (self-signed cert)", checked: true })}</div><div class="field-grid">${field({ id: "wtHashValue", label: "Certificate hash (SHA-256, hex)", value: "a1b2c3d4e5f6...", attrs: 'style="width:200px"' })}${checkbox({ id: "wtBidi", label: "Show bidirectional stream example", checked: true })}</div>`,generate(root) {const host = root.querySelector("#wtHost").value.trim() || "example.com";const port = root.querySelector("#wtPort").value.trim() || "4433";const path = root.querySelector("#wtPath").value.trim() || "/webtransport";const includeHash = root.querySelector("#wtHash").checked;const hashVal = root.querySelector("#wtHashValue").value.trim() || "a1b2c3d4e5f6...";const showBidi = root.querySelector("#wtBidi").checked;const url = `https://${host}:${port}${path}`;const lines = [];lines.push("// WebTransport — Baseline 2026");lines.push("// Browser: Chrome 97+, Edge 97+, Safari ✗, Firefox ✗ (planned)");lines.push("// Low-latency client-server messaging over HTTP/3 (QUIC).");lines.push("// Alternative to WebSockets with multiplexed streams and datagrams.");lines.push("");lines.push(`// Connect to WebTransport server`);lines.push(`const url = '${url}';`);lines.push("");if (includeHash) {lines.push(`const transport = new WebTransport(url, {`);lines.push(" serverCertificateHashes: [");lines.push(" {");lines.push(` algorithm: 'sha-256',`);lines.push(` value: new Uint8Array(${hashVal.match(/\w\w/g) ? "[" + hashVal.match(/\w\w/g).map(h => "0x" + h).join(", ") + "]" : "[]"})`);lines.push(" }");lines.push(" ]");lines.push("});");} else {lines.push("const transport = new WebTransport(url);");}lines.push("");lines.push("await transport.ready;");lines.push("console.log('WebTransport connected');");lines.push("");if (showBidi) {lines.push("// Open a bidirectional stream");lines.push("const stream = await transport.createBidirectionalStream();");lines.push("const writer = stream.writable.getWriter();");lines.push("const reader = stream.readable.getReader();");lines.push("");lines.push("// Send data");lines.push("await writer.write(new TextEncoder().encode('Hello, server!'));");lines.push("");lines.push("// Receive data");lines.push("const { value, done } = await reader.read();");lines.push("if (value) console.log('Received:', new TextDecoder().decode(value));");}lines.push("");lines.push("// Receive incoming unidirectional streams");lines.push("transport.incomingUnidirectionalStreams.getReader().read().then(({ value }) => {");lines.push(" // handle incoming stream");lines.push("});");lines.push("");lines.push("// Datagrams (unreliable delivery, like UDP)");lines.push("const datagramWriter = transport.datagrams.writable.getWriter();");lines.push("await datagramWriter.write(new Uint8Array([1, 2, 3]));");lines.push("");lines.push("// Cleanup");lines.push("transport.close();");lines.push("");lines.push("// Notes:");lines.push("// 1. WebTransport requires HTTP/3 (QUIC) support on the server.");lines.push("// 2. Self-signed certificates are supported via serverCertificateHashes.");lines.push("// 3. Use for real-time games, live streaming, and low-latency data exchange.");lines.push("// 4. WebTransport can replace WebSockets + WebRTC data channels for many use cases.");const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:14px;background:#f9fafb"><div style="font-size:13px;font-weight:600;color:#374151;margin-bottom:8px">WebTransport: ${url}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px"><span style="background:#dcfce7;color:#166534;padding:3px 10px;border-radius:12px;font-size:11px">HTTP/3 (QUIC)</span><span style="background:#dbeafe;color:#1e40af;padding:3px 10px;border-radius:12px;font-size:11px">Bidirectional streams</span><span style="background:#dbeafe;color:#1e40af;padding:3px 10px;border-radius:12px;font-size:11px">Datagrams</span>${includeHash ? '<span style="background:#fef3c7;color:#92400e;padding:3px 10px;border-radius:12px;font-size:11px">Self-signed cert</span>' : ""}</div><div style="font-family:monospace;font-size:12px;background:#fff;padding:10px;border-radius:6px;border:1px solid #e5e7eb">new WebTransport('${url}') &rarr; transport.ready</div></div>`;return { output: lines.join("\n"), preview };}};